-- T135 (the full review of 2026-10-24 on ecb0388, M2; the owner's decision of 2026-10-29).
-- Generated by `prisma migrate diff --from-config-datasource --to-schema prisma/schema --script`
-- against a database holding every migration before it.
--
-- What it lands: the four foreign keys of the three append-only tables (ERD section 15.21),
-- `audit_logs.admin_id`, `payment_events.payment_id`, `session_participant_events.session_id` and
-- `session_participant_events.user_id`, go from `ON UPDATE CASCADE` (`20261007000000_init`) to
-- `ON UPDATE RESTRICT`. The cascade ran as the table's owner, so an UPDATE of the referenced key,
-- which the application role holds on `admin_users`, `payments`, `sessions` and `users`, rewrote an
-- event row past the UPDATE that `20261007000500_append_only_tables` revoked. Now that key update is
-- refused while a row references it. `ON DELETE RESTRICT` is unchanged. The relations in
-- `prisma/schema/` say `onUpdate: Restrict`, so a later generated migration does not restore the
-- cascade.

-- DropForeignKey
ALTER TABLE "audit_logs" DROP CONSTRAINT "audit_logs_admin_id_fkey";

-- DropForeignKey
ALTER TABLE "payment_events" DROP CONSTRAINT "payment_events_payment_id_fkey";

-- DropForeignKey
ALTER TABLE "session_participant_events" DROP CONSTRAINT "session_participant_events_session_id_fkey";

-- DropForeignKey
ALTER TABLE "session_participant_events" DROP CONSTRAINT "session_participant_events_user_id_fkey";

-- AddForeignKey
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_admin_id_fkey" FOREIGN KEY ("admin_id") REFERENCES "admin_users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "payment_events" ADD CONSTRAINT "payment_events_payment_id_fkey" FOREIGN KEY ("payment_id") REFERENCES "payments"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "session_participant_events" ADD CONSTRAINT "session_participant_events_session_id_fkey" FOREIGN KEY ("session_id") REFERENCES "sessions"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "session_participant_events" ADD CONSTRAINT "session_participant_events_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
